import sys, os, struct, zlib, hashlib
pack_path, idx_path, outdir = sys.argv[1], sys.argv[2], sys.argv[3]
pack = open(pack_path,'rb').read(); idx = open(idx_path,'rb').read()
fan = struct.unpack('>256I', idx[8:8+1024]); n = fan[255]; p = 8+1024
shas = [idx[p+20*i:p+20*i+20].hex() for i in range(n)]; p += 20*n
crcs = struct.unpack('>%dI'%n, idx[p:p+4*n]); p += 4*n
offs = list(struct.unpack('>%dI'%n, idx[p:p+4*n])); p += 4*n
entries = sorted(zip(offs, shas, crcs)); end_data = len(pack)-20
off2sha = {o:s for o,s,_ in entries}
TYPES = {1:'commit',2:'tree',3:'blob',4:'tag',6:'ofs_delta',7:'ref_delta'}
def read_hdr(data, pos):
    c = data[pos]; pos += 1; t = (c>>4)&7; size = c&15; shift = 4
    while c & 0x80:
        c = data[pos]; pos += 1; size |= (c&0x7f)<<shift; shift += 7
    return t, size, pos
def read_ofs(data, pos):
    c = data[pos]; pos += 1; off = c&0x7f
    while c & 0x80:
        c = data[pos]; pos += 1; off = ((off+1)<<7)|(c&0x7f)
    return off, pos
def varint(buf, pos):
    v = 0; shift = 0
    while True:
        c = buf[pos]; pos += 1; v |= (c&0x7f)<<shift; shift += 7
        if not c & 0x80: return v, pos
def apply_delta(base, delta):
    pos = 0
    bsize, pos = varint(delta, pos); rsize, pos = varint(delta, pos)
    assert bsize == len(base), ("base size mismatch", bsize, len(base))
    out = bytearray()
    while pos < len(delta):
        op = delta[pos]; pos += 1
        if op & 0x80:
            cp_off = 0; cp_size = 0
            for i in range(4):
                if op & (1<<i): cp_off |= delta[pos] << (8*i); pos += 1
            for i in range(3):
                if op & (1<<(4+i)): cp_size |= delta[pos] << (8*i); pos += 1
            if cp_size == 0: cp_size = 0x10000
            out += base[cp_off:cp_off+cp_size]
        elif op:
            out += delta[pos:pos+op]; pos += op
        else: raise ValueError("bad delta op 0")
