cat > /tmp/scripts/loose_repair.py <<'EOF'
import sys, zlib, hashlib, os
repo = sys.argv[1]
shas = [l.strip() for l in open('/tmp/loose_corrupt.txt')]
def try_full(data):
    try:
        out = zlib.decompress(data)
    except zlib.error:
        return None
    nul = out.find(b'\0')
    if nul < 0: return None
    try:
        t, s = out[:nul].decode().split()
        if int(s) != len(out)-nul-1: return None
    except Exception: return None
    return hashlib.sha1(out).hexdigest(), t, out[nul+1:]
def partial(data):
    d = zlib.decompressobj(); out = b''; pos = 0; err = None
    # feed byte by byte to find failure point
    for i in range(len(data)):
        try:
            out += d.decompress(data[i:i+1])
        except zlib.error as e:
            err = str(e); pos = i; break
    else:
        pos = len(data)
    return out, pos, err, d.eof if err is None else False
for sha in shas:
    path = os.path.join(repo, 'objects', sha[:2], sha[2:])
    data = open(path,'rb').read()
    print("=" * 70); print(sha, "filesize", len(data), "zlib hdr", data[:2].hex())
    out, pos, err, eof = partial(data)
    print("partial inflate: %d bytes out, failed at input byte %d/%d err=%s eof=%s" % (len(out), pos, len(data), err, eof))
    print("partial content repr:", repr(out[:400]))
    # single byte substitution brute force
    found = []
    for i in range(len(data)):
        orig = data[i]
        for v in range(256):
            if v == orig: continue
            cand = data[:i] + bytes([v]) + data[i+1:]
            r = try_full(cand)
            if r and r[0] == sha:
                found.append((i, orig, v, r[1])); break
        if found: break
    if found:
        i, orig, v, t = found[0]
        print("REPAIRED by single-byte substitution at %d: 0x%02x -> 0x%02x (type %s)" % (i, orig, v, t))
        fixed = data[:i] + bytes([v]) + data[i+1:]
        open('/tmp/repaired_%s' % sha, 'wb').write(fixed)
    else:
        # try single byte deletion and insertion
        done = False
        for i in range(len(data)):
            cand = data[:i] + data[i+1:]
